/**
 * AC-2-15 Verification Report Template Generator
 *
 * Auto-generated by /rpi:research phase2 AC-2-15
 * Parses landednz_kb_master_COMPLETE_v1.md and creates structured verification template
 *
 * Usage: npx ts-node scripts/generate-ac-2-15-template.ts
 * Output: rpi/phase2-roadmap-engine/research/AC-2-15-verification-report.md
 */

import { readFileSync, writeFileSync, existsSync } from 'fs'
import { logger } from '../src/shared/logger'

interface TaskInfo {
  taskId: string
  taskName: string
  sourceUrl: string
  typeBNumbers: string[]
  hasProfessionalAdvice: boolean
  personaVariants: string[]
}

interface UrlCheckResult {
  taskId: string
  status: string
  statusCode?: number
  errorMessage?: string
}

function parseKnowledgeBase(): TaskInfo[] {
  const kbPath = '/Users/ruchira/Development/landednz/landednz_kb_master_COMPLETE_v1.md'

  try {
    const content = readFileSync(kbPath, 'utf-8')
    const tasks: TaskInfo[] = []

    // Parse T01-T21 tasks
    const taskBlocks = content.split(/^## (T\d{2})/m).slice(1)

    for (let i = 0; i < taskBlocks.length; i += 2) {
      const taskId = taskBlocks[i]
      const taskContent = taskBlocks[i + 1] || ''

      // Extract task name
      const nameMatch = taskContent.match(/^[^\n]+/)
      const taskName = nameMatch ? nameMatch[0].trim() : 'Unknown task'

      // Extract primary source URL
      let sourceUrl = 'No source URL found'
      const sourcesMatch = taskContent.match(/SOURCES:\s*\n([^#]*?)(?=\n#|\n\n|\s*$)/s)
      if (sourcesMatch) {
        const sourcesSection = sourcesMatch[1]
        const urlMatch = sourcesSection.match(/https?:\/\/[^\s\)]+/)
        if (urlMatch) {
          sourceUrl = urlMatch[0]
        }
      }

      // Extract Type B numbers from KEY_FACTS
      const typeBNumbers: string[] = []
      const keyFactsMatch = taskContent.match(/KEY_FACTS:\s*\n([^#]*?)(?=\n#|\n\n|\s*$)/s)
      if (keyFactsMatch) {
        const keyFacts = keyFactsMatch[1]
        // Look for currency amounts, percentages, timeframes
        const numberPatterns = [
          /\$\d+(?:,\d{3})*(?:\.\d{2})?/g,  // $500, $1,000.50
          /NZD?\s*\$?\d+/g,                  // NZD $445, NZ$300
          /\d+%/g,                           // 15%
          /\d+\s*(?:days?|weeks?|months?)/g  // 15 days, 2 weeks
        ]

        numberPatterns.forEach(pattern => {
          const matches = keyFacts.match(pattern) || []
          typeBNumbers.push(...matches)
        })
      }

      // Check for professional advice requirement
      const hasProfessionalAdvice = taskContent.includes('PROFESSIONAL_ADVICE_REQUIRED: true')

      // Extract persona variants
      const personaVariants: string[] = []
      if (taskContent.includes('PERSONA_CONSTRAINED_COUPLE')) {
        personaVariants.push('constrained_couple')
      }
      if (taskContent.includes('PERSONA_SOLO_AEWV')) {
        personaVariants.push('solo_aewv')
      }

      tasks.push({
        taskId,
        taskName,
        sourceUrl,
        typeBNumbers: [...new Set(typeBNumbers)], // Remove duplicates
        hasProfessionalAdvice,
        personaVariants
      })
    }

    return tasks
  } catch (error) {
    logger.error({ error, kbPath }, 'Failed to parse knowledge base file')
    throw new Error(`Failed to read knowledge base: ${error instanceof Error ? error.message : 'Unknown error'}`)
  }
}

function loadUrlCheckResults(): Record<string, UrlCheckResult> {
  const reportPath = 'rpi/phase2-roadmap-engine/research/AC-2-15-url-report.json'

  if (!existsSync(reportPath)) {
    logger.warn('URL check report not found, template will show unknown status')
    return {}
  }

  try {
    const reportContent = readFileSync(reportPath, 'utf-8')
    const report = JSON.parse(reportContent)

    const resultMap: Record<string, UrlCheckResult> = {}
    report.results?.forEach((result: any) => {
      resultMap[result.taskId] = result
    })

    return resultMap
  } catch (error) {
    logger.error({ error, reportPath }, 'Failed to load URL check results')
    return {}
  }
}

function generateTemplate(tasks: TaskInfo[], urlResults: Record<string, UrlCheckResult>): string {
  const template = `# AC-2-15 Verification Report
*Generated: ${new Date().toISOString()}*
*Status: TEMPLATE — Human must complete manual verification*

## Overview

This report tracks the verification of all T01-T21 tasks before seeding to the database.
Each task must be manually verified against its live government source.

**Requirements:**
- ✅ All source URLs must return HTTP 200
- ✅ Key facts in WHAT_AND_WHY must match live government page
- ✅ Steps in HOW_TO must be current and accurate
- ✅ All Type B numbers must match current published figures
- ✅ Both persona variants required for every task

## URL Liveness Check Results

| Task | URL Status | Source URL | Notes |
|------|------------|------------|-------|
${tasks.map(task => {
  const urlResult = urlResults[task.taskId]
  const status = urlResult ? urlResult.status : 'unknown'
  const statusIcon = status === 'success' ? '✅' : status === 'error' ? '❌' : status === 'redirect' ? '⚠️' : '❓'
  const notes = urlResult?.errorMessage || urlResult?.statusCode || ''

  return `| ${task.taskId} | ${statusIcon} ${status} | ${task.sourceUrl} | ${notes} |`
}).join('\n')}

## Task Verification Checklist

Complete this section by manually verifying each task:

${tasks.map(task => `
### ${task.taskId} — ${task.taskName}

**Source:** ${task.sourceUrl}

**Manual Verification Status:** ☐ PENDING / ☐ PASS / ☐ FAIL

**Content Verification:**
- ☐ WHAT_AND_WHY facts match live government page
- ☐ HOW_TO steps are current and accurate
- ☐ Source URL content matches KB content

**Type B Numbers Requiring Verification:**
${task.typeBNumbers.length > 0
  ? task.typeBNumbers.map(num => `- ☐ ${num} — current rate confirmed at source`).join('\n')
  : '- No Type B numbers identified'
}

**Persona Variants:**
${task.personaVariants.map(variant => `- ☐ ${variant} variant complete and accurate`).join('\n')}

**Professional Advice:**
${task.hasProfessionalAdvice
  ? '- ☐ Professional advice requirement verified and note included'
  : '- N/A — No professional advice required'
}

**Verification Notes:**
*[Record any discrepancies, updates needed, or special notes]*

---`).join('\n')}

## Summary

**Total Tasks:** ${tasks.length}
**URL Check Status:** ${Object.values(urlResults).filter(r => r.status === 'success').length}/${tasks.length} URLs live

**Overall Status:** ☐ ALL TASKS VERIFIED / ☐ VERIFICATION IN PROGRESS / ☐ VERIFICATION FAILED

**Issues Found:**
*[List any tasks that failed verification, URLs that are dead, or content that needs updates]*

**Next Steps:**
- [ ] Complete manual verification for all tasks above
- [ ] Resolve any content discrepancies found
- [ ] Confirm all Type B numbers are current
- [ ] Verify all source URLs are accessible
- [ ] Present completed report for review before seeding

---

*When verification is complete, rename this file to AC-2-15-final-verification.md*
*Do NOT proceed with seeding until all checkboxes above are marked ✅*`

  return template
}

async function main() {
  logger.info('Generating AC-2-15 verification report template')

  try {
    // Parse knowledge base
    const tasks = parseKnowledgeBase()
    logger.info({ taskCount: tasks.length }, 'Parsed tasks from knowledge base')

    // Load URL check results if available
    const urlResults = loadUrlCheckResults()
    logger.info({ urlResultCount: Object.keys(urlResults).length }, 'Loaded URL check results')

    // Generate template
    const template = generateTemplate(tasks, urlResults)

    // Write template
    const outputPath = 'rpi/phase2-roadmap-engine/research/AC-2-15-verification-report.md'
    writeFileSync(outputPath, template)

    logger.info({ outputPath }, 'Verification report template generated')

    console.log('\\n=== AC-2-15 VERIFICATION TEMPLATE GENERATED ===')
    console.log(`Location: ${outputPath}`)
    console.log(`Tasks found: ${tasks.length}`)
    console.log('\\nNext steps:')
    console.log('1. Complete manual verification for each task')
    console.log('2. Check all source URLs are accessible')
    console.log('3. Verify Type B numbers against live sources')
    console.log('4. Present completed report before seeding')

  } catch (error) {
    logger.error(error, 'Template generation failed')
    process.exit(1)
  }
}

main()